class AsyncKycLivenessResource(AsyncResource):
    """Operations of `client.kyc.liveness`."""

    async def start(
        self,
        *,
        redirect_url: str | None = None,
        **options: Unpack[RequestOptions],
    ) -> KycLivenessSession:
        """Start a liveness check.

        Requested after an API call fails with 400 `LIVENESS_VERIFICATION_REQUIRED`; once the check
        passes the web app replays the failed call. With status `PROCESSING` the client opens
        `iframeUrl` (the PIN provider, origin `https://verification.svort.io`) on this device or
        shows it as a QR code for another device, then polls `kyc.liveness.status` every 2 seconds.

        Args:
            redirect_url: Where the provider returns after the check; the web app sends it only for
                the redirect flow (in-app web views and the Telegram bot).
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The response as `KycLivenessSession`.
        """
        return await self._engine.request(
            "api",
            "POST",
            "/api/v2/kyc/liveness/start",
            json={"redirectUrl": redirect_url},
            cast_to=KycLivenessSession,
            options=options,
        )

    async def retry(
        self,
        **options: Unpack[RequestOptions],
    ) -> KycLivenessSession:
        """Restart a liveness check.

        Used when the status is `RETRY_NEEDED` or the QR code expired. Statuses
        `MAX_ATTEMPTS_EXCEEDED` and `LIVENESS_NOT_FOUND` mean no further attempt is possible.

        Args:
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The response as `KycLivenessSession`.
        """
        return await self._engine.request(
            "api",
            "POST",
            "/api/v2/kyc/liveness/retry",
            json={},
            cast_to=KycLivenessSession,
            options=options,
        )

    async def status(
        self,
        **options: Unpack[RequestOptions],
    ) -> KycLivenessStatus | str:
        """Get the liveness check status.

        Returns the status as a bare string. `PASSED` is success, `PROCESSING` means keep polling,
        `RETRY_NEEDED` calls for `kyc.liveness.retry`; `EXPIRED`, `FAILED` and `ERROR` end the
        check.

        Args:
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The response as `KycLivenessStatus | str`.
        """
        return cast(
            "KycLivenessStatus | str",
            await self._engine.request(
                "api",
                "GET",
                "/api/v2/kyc/liveness/status",
                cast_to=KycLivenessStatus | str,
                options=options,
            ),
        )


